(function () {
  function domReady(callback) {
    if (['interactive', 'complete'].indexOf(document.readyState) >= 0) {
      callback();
    } else {
      document.addEventListener('DOMContentLoaded', callback);
    }
  }

  function readCookie(name) {
    var cookies = document.cookie ? document.cookie.split(';') : [];

    for (var i = 0; i < cookies.length; i++) {
      var cookie = cookies[i].replace(/^\s+/, '');

      if (cookie.indexOf(name + '=') === 0) {
        try {
          return decodeURIComponent(cookie.substring(name.length + 1));
        } catch (error) {
          return cookie.substring(name.length + 1);
        }
      }
    }

    return '';
  }

  function hasCategoryConsent(categories, names) {
    if (!categories) {
      return false;
    }

    for (var i = 0; i < names.length; i++) {
      if (typeof categories === 'string' && categories.indexOf(names[i] + ':true') !== -1) {
        return true;
      }

      if (typeof categories !== 'string' && categories[names[i]]) {
        return true;
      }
    }

    return false;
  }

  function getStoredHubSpotConsent() {
    var preference = readCookie('__hs_cookie_cat_pref');

    if (!preference) {
      return null;
    }

    return {
      analytics: hasCategoryConsent(preference, ['1', 'analytics', 'analytical']),
      advertisement: hasCategoryConsent(preference, ['2', 'advertisement', 'advertising']),
      marketing: hasCategoryConsent(preference, ['3', 'marketing', 'performance'])
    };
  }

  var lastHubSpotConsentSignature = '';
  var lastStoredHubSpotConsentCookie = '';
  var hubSpotConsentEventDelay = 100;
  var gtmContainerId = 'GTM-TQ9GT6MJ';
  var isGtmLoading = false;
  var isGtmLoaded = false;
  var hasQueuedGtmEvent = false;
  var latestGtmConsentState = {
    analytics: false,
    advertisement: false,
    marketing: false
  };

  function gtag() {
    window.dataLayer = window.dataLayer || [];
    window.dataLayer.push(arguments);
  }

  function updateGoogleConsentMode(analytics, advertisement) {
    gtag('consent', 'default', {
      analytics_storage: 'denied',
      ad_storage: 'denied',
      ad_user_data: 'denied',
      ad_personalization: 'denied',
      wait_for_update: 1000
    });

    gtag('consent', 'update', {
      analytics_storage: analytics ? 'granted' : 'denied',
      ad_storage: advertisement ? 'granted' : 'denied',
      ad_user_data: advertisement ? 'granted' : 'denied',
      ad_personalization: advertisement ? 'granted' : 'denied'
    });
  }

  function pushHubSpotConsentEvent(analytics, advertisement, marketing) {
    window.dataLayer = window.dataLayer || [];
    window.dataLayer.push({
      event: 'hubspot_consent_update',
      hubspot_consent_analytics: analytics,
      hubspot_consent_advertisement: advertisement,
      hubspot_consent_marketing: marketing
    });
  }

  function loadGoogleTagManager(analytics, advertisement, marketing) {
    var shouldLoadGtm = analytics || advertisement || marketing;

    latestGtmConsentState = {
      analytics: analytics,
      advertisement: advertisement,
      marketing: marketing
    };

    updateGoogleConsentMode(analytics, advertisement);

    if (!shouldLoadGtm) {
      pushHubSpotConsentEvent(analytics, advertisement, marketing);
      return;
    }

    if (isGtmLoaded) {
      pushHubSpotConsentEvent(analytics, advertisement, marketing);
      return;
    }

    hasQueuedGtmEvent = true;

    if (isGtmLoading) {
      return;
    }

    isGtmLoading = true;
    window.dataLayer = window.dataLayer || [];
    window.dataLayer.push({
      'gtm.start': new Date().getTime(),
      event: 'gtm.js'
    });

    var firstScript = document.getElementsByTagName('script')[0];
    var gtmScript = document.createElement('script');

    gtmScript.async = true;
    gtmScript.src = 'https://www.googletagmanager.com/gtm.js?id=' + gtmContainerId;
    gtmScript.onload = function () {
      isGtmLoaded = true;

      if (hasQueuedGtmEvent) {
        hasQueuedGtmEvent = false;
        pushHubSpotConsentEvent(
          latestGtmConsentState.analytics,
          latestGtmConsentState.advertisement,
          latestGtmConsentState.marketing
        );
      }
    };

    window.setTimeout(function () {
      if (hasQueuedGtmEvent) {
        hasQueuedGtmEvent = false;
        pushHubSpotConsentEvent(
          latestGtmConsentState.analytics,
          latestGtmConsentState.advertisement,
          latestGtmConsentState.marketing
        );
      }
    }, 1500);

    if (firstScript && firstScript.parentNode) {
      firstScript.parentNode.insertBefore(gtmScript, firstScript);
    } else if (document.head) {
      document.head.appendChild(gtmScript);
    }
  }

  function pushHubSpotConsentUpdate(consentState) {
    var analytics = !!(consentState && consentState.analytics);
    var advertisement = !!(consentState && consentState.advertisement);
    var marketing = !!(consentState && consentState.marketing);
    var signature = analytics + ':' + advertisement + ':' + marketing;

    if (signature === lastHubSpotConsentSignature) {
      return;
    }

    lastHubSpotConsentSignature = signature;

    window.setTimeout(function () {
      loadGoogleTagManager(analytics, advertisement, marketing);
    }, hubSpotConsentEventDelay);
  }

  function syncStoredHubSpotConsent() {
    var preference = readCookie('__hs_cookie_cat_pref');

    if (!preference || preference === lastStoredHubSpotConsentCookie) {
      return;
    }

    lastStoredHubSpotConsentCookie = preference;
    pushHubSpotConsentUpdate(getStoredHubSpotConsent());
  }

  window._hsp = window._hsp || [];
  window._hsp.push([
    'addPrivacyConsentListener',
    function (consent) {
      var allowed = !!(consent && consent.allowed);
      var categories = (consent && consent.categories) || {};

      pushHubSpotConsentUpdate({
        analytics: allowed || hasCategoryConsent(categories, ['1', 'analytics', 'analytical']),
        advertisement: allowed || hasCategoryConsent(categories, ['2', 'advertisement', 'advertising']),
        marketing: allowed || hasCategoryConsent(categories, ['3', 'marketing', 'performance'])
      });
    }
  ]);

  domReady(function () {
    window.setTimeout(function () {
      syncStoredHubSpotConsent();
    }, 1500);

    window.setInterval(syncStoredHubSpotConsent, 1000);
  });
})();

