div.script:
(function () {
  var megamenu = document.querySelector('[data-megamenu]');
  if (!megamenu) return;

  function applyStickyTop() {
    megamenu.classList.add('megamenu--sticky');
    megamenu.classList.remove('megamenu--transparent');
  }

  /* Loading with an anchor hash: the page jumps to the target section, so keep
     the nav hidden rather than flashing the sticky bar over it. initMegamenu
     re-seats the section flush once it hydrates. */
  if (window.location.hash && window.location.hash.length > 1) {
    megamenu.classList.add('megamenu--hidden');
    megamenu.classList.remove('megamenu--transparent');
    return;
  }

  if (window.scrollY > 0) {
    applyStickyTop();
    return;
  }

  megamenu.classList.add('megamenu--transparent');

  document.addEventListener('DOMContentLoaded', function () {
    if (window.scrollY > 0) return;
    if (document.querySelector('[data-subservice-page-hero], [data-megamenu-light]')) {
      applyStickyTop();
    }
  });
})();

